// The deck's project as one bundle, kept with each published version so
// anyone on the team can update the deck later, from any machine.
//
//   node bin/source.mjs pack          writes artifacts/source.json and prints {"size": n}
//                                     (pass it as deck_upload_start's source; npm run upload sends it)
//   node bin/source.mjs pull <url>    unpacks a bundle (deck_source's download_url, or a file) here
//
// Format, shared with the deck studio: {"files":[{"path","b64"}]} holding
// story.md, src/, brand/, and public/. src/brand is generated by every build
// and brand/capture is evidence, so neither is kept.
import { mkdir, readdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join, normalize, relative, sep } from 'node:path';
import { scanSource } from './source-guard.mjs';

export const SOURCE_ROOTS = ['story.md', 'src', 'brand', 'public'];
export const SOURCE_LIMITS = { fileBytes: 3 * 1024 * 1024, totalBytes: 15 * 1024 * 1024 };
const SKIP = [join('src', 'brand') + sep, join('brand', 'capture') + sep];
const OUT = join('artifacts', 'source.json');

/** Whether a bundle path is one this project may hold: relative, inside a source root, no "..". */
export function safeSourcePath(path) {
  if (typeof path !== 'string' || !path || path.includes('\0') || path.startsWith('/') || path.includes('\\')) return false;
  const clean = normalize(path);
  if (clean !== path || clean.split('/').includes('..')) return false;
  return SOURCE_ROOTS.some((root) => clean === root || clean.startsWith(`${root}/`));
}

async function* walk(path) {
  const info = await stat(path).catch(() => null);
  if (!info) return;
  if (info.isFile()) {
    yield path;
    return;
  }
  for (const entry of await readdir(path, { withFileTypes: true })) {
    if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
    yield* walk(join(path, entry.name));
  }
}

/** Collect the project's files into a bundle. Oversized files are left out and listed. */
export async function pack(root = '.') {
  const files = [];
  const skipped = [];
  let total = 0;
  for (const top of SOURCE_ROOTS) {
    for await (const full of walk(join(root, top))) {
      const path = relative(root, full).split(sep).join('/');
      if (SKIP.some((s) => `${relative(root, full)}${sep}`.startsWith(s) || relative(root, full).startsWith(s))) continue;
      const body = await readFile(full);
      if (body.length > SOURCE_LIMITS.fileBytes || total + body.length > SOURCE_LIMITS.totalBytes) {
        skipped.push(path);
        continue;
      }
      total += body.length;
      files.push({ path, b64: body.toString('base64') });
    }
  }
  return { bundle: { files }, skipped };
}

/**
 * Write a bundle's files into the project, after checking nothing in it
 * reaches past the deck (source-guard.mjs). If anything does, nothing is
 * written. Slides are replaced as a set, so a starter's examples don't linger.
 */
export async function unpack(bundle, root = '.') {
  if (!bundle || !Array.isArray(bundle.files)) throw new Error('Not a deck source bundle (expected {"files":[...]}).');
  const files = bundle.files.filter((f) => safeSourcePath(f?.path) && typeof f.b64 === 'string');
  const refused = bundle.files.length - files.length;
  const findings = scanSource(files.map((f) => ({ path: f.path, text: Buffer.from(f.b64, 'base64').toString('utf8') })));
  if (findings.length) {
    const list = findings.slice(0, 12).map((f) => `  ${f.path}:${f.line} ${f.why}`).join('\n');
    const error = new Error(
      `Not pulling this deck: its code reaches outside the deck, which a deck never needs to do.\n${list}${findings.length > 12 ? `\n  …and ${findings.length - 12} more` : ''}\nNothing was written. Tell the user, and ask whoever published it to take that out.`,
    );
    error.findings = findings;
    throw error;
  }
  if (files.some((f) => f.path.startsWith('src/slides/'))) await rm(join(root, 'src', 'slides'), { recursive: true, force: true });
  for (const f of files) {
    const target = join(root, f.path);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, Buffer.from(f.b64, 'base64'));
  }
  return { written: files.length, refused };
}

async function main() {
  const [command, from] = process.argv.slice(2);
  if (command === 'pack') {
    const { bundle, skipped } = await pack();
    const body = Buffer.from(JSON.stringify(bundle));
    await mkdir('artifacts', { recursive: true });
    await writeFile(OUT, body);
    if (skipped.length) console.error(`Left out of the source bundle (too big; keep large media out of public/): ${skipped.join(', ')}`);
    console.log(JSON.stringify({ size: body.length, files: bundle.files.length, path: OUT }));
    return;
  }
  if (command === 'pull' && from) {
    const text = /^https?:\/\//.test(from)
      ? await fetch(from).then(async (r) => {
          if (!r.ok) throw new Error(`Download failed (HTTP ${r.status}). The link lasts 15 minutes; call deck_source again for a fresh one.`);
          return r.text();
        })
      : await readFile(from, 'utf8');
    const { written, refused } = await unpack(JSON.parse(text));
    console.log(`Unpacked ${written} file(s) into this project${refused ? `; refused ${refused} with unsafe paths` : ''}. Run npm run build, then check and review as usual before publishing.`);
    return;
  }
  console.error('Usage: node bin/source.mjs pack | pull <download_url or file>');
  process.exit(2);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    process.exit(1);
  });
}
